<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';$user=require_login();ensure_lead_schema();$manager=can_view_all_sales_financials($user);$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();try{
    match(sales_text($_POST,'action',1,30)){
      'read'=>sales_notification_read($user,sales_text($_POST,'event_key',64,64)),
      'activity'=>sales_activity_record($user,$_POST),
      'target'=>sales_target_save($user,$_POST),
      'grant'=>sales_staff_grant($user,$_POST),
      'email'=>db()->prepare('INSERT INTO sales_notification_preferences(user_id,email_enabled) VALUES(?,?) ON DUPLICATE KEY UPDATE email_enabled=VALUES(email_enabled)')->execute([$user['id'],($_POST['enabled']??'')==='1'?1:0]),
      default=>throw new InvalidArgumentException('Μη έγκυρη ενέργεια.')
    };flash('success','Η ενέργεια καταγράφηκε.');redirect_to('operations.php');
 }catch(Throwable $e){$error=$e instanceof InvalidArgumentException?$e->getMessage():'Η ενέργεια δεν ολοκληρώθηκε.';}
}
$month=is_string($_GET['month']??null)?$_GET['month']:date('Y-m');try{$report=sales_activity_report($user,$month);}catch(InvalidArgumentException){http_response_code(400);exit('Μη έγκυρος μήνας.');}
$feed=sales_notification_feed($user);$q=db()->prepare('SELECT email_enabled FROM sales_notification_preferences WHERE user_id=?');$q->execute([$user['id']]);$preference=$q->fetchColumn();
render_header('Εσωτερικές εργασίες',$user);
?>
<div class="page-heading"><div><h1>Εσωτερικές εργασίες</h1><p>Ενημερώσεις, πραγματικές εμπορικές ενέργειες και στόχοι ομάδας — χωρίς αυτόματη επικοινωνία με πελάτες.</p></div><a class="button" href="<?= e(crm_url('sales-portal.php')) ?>">Sales Portal</a></div>
<?php if($error): ?><p class="alert error"><?= e($error) ?></p><?php endif; ?>
<section class="card form-section"><h2>Οι ειδοποιήσεις μου</h2>
<?php foreach($feed as $notice): ?><article class="card"><a href="<?= e(crm_url($notice['url'])) ?>"><?= e($notice['label']) ?></a><?php if($notice['read']): ?><p>Αναγνωσμένη</p><?php else: ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="read"><input type="hidden" name="event_key" value="<?= e($notice['key']) ?>"><button class="button small">Σημείωση ως αναγνωσμένη</button></form><?php endif; ?></article><?php endforeach; ?>
<?php if(!$feed): ?><p>Δεν υπάρχουν τρέχουσες ειδοποιήσεις.</p><?php endif; ?>
